L('follow','confront',A,F,[("The minutes have you there.","calm",K)],after='lie')
L('follow','thank',A,F,[("Then I'll put that you deny it.","calm")],after='lie')
L('reply','answer',Y,F,[("I'm paying it back, and I've asked the clerk to post the records. You can have them tomorrow.","calm")],after='Fixing it how?')
L('reply','deny',Y,F,[("One thing: the date's wrong. I can send you the calendar.","calm")],after='press')
