# ================= BATCH 17: eight new situations =================
KEY.update({"first-day-ropes":"arrival","last-day-farewell":"departure","poll-problem":"routine","concession-call":"loss","victory-night":"honor","signing-ask":"honor","veto-call":"loss","mentor-advice":"routine"})
F='first-day-ropes'
L(N,N,R,F,[("It's your first morning at {office}. {name}, who's been there longer than anyone, is waiting with a ring of keys.","curious")])
