L('follow','answer',A,F,[("Somebody who left in a hurry. You'll find their coffee mug in the drawer.","calm")],after="Who had this job before me?")
L('follow','accept',A,F,[("A normal day. Bring coffee. It's a long one.","calm")],after='tell')
L('follow','confront',A,F,[("Some don't. The ones who ask that on day one usually do.","braced")],after='confront')
L('follow','apologize',A,F,[("Fair question. It's been a rough year. I'll tell you why over lunch.","contrite")],after='confront')
L('reply','answer',Y,F,[("Then hand it to me anyway. I'd rather know the worst of it first.","calm")],after='warn')
L('reply','ask',Y,F,[("What does everybody else avoid?","curious")],after='warn')
L('reply','apologize',Y,F,[("Then I'll be the one who lasts. What do I need to know first?","contrite")],after="Some don't. The ones who ask that on day one usually do.")
L('reply','confront',Y,F,[("I'll ask around, then.","braced")],after="Some don't. The ones who ask that on day one usually do.")
L('reply','thank',Y,F,[("Thank you. Show me.","calm")],after='apologize')
L('reply','leave',Y,F,[("Let me put my things down first.","calm")])
L('close','accept',A,F,[("Through the kitchen. Watch the wet floor.","calm")],after='leave',outcome='open')
L('close','thank',A,F,[("Welcome aboard.","glad")],outcome='resolved')
F='last-day-farewell'
L(N,N,R,F,[("Your office is boxes now. {name} leans in the doorway like they've done a hundred times.","solemn")])
L('open','greet',A,F,[("So that's it, then.","solemn")])
L('state','ask',A,F,[("Off the record, now that it doesn't matter. Was it worth it?","curious")])
L('reply','tell',Y,F,[("Most days, no. The days it was, it was worth all the rest. You know which ones I mean.","tender")])
L('reply','ask',Y,F,[("Are you staying on with whoever's next?","curious")])
L('reply','promise',Y,F,[("Ask me in a year, over lunch. I'm buying.","tender")])
L('reply','deflect',Y,F,[("Help me with this box, and I'll tell you.","calm")])
L('follow','ask',A,F,[("Which one would you do over?","curious")],after='tell')
L('follow','answer',A,F,[("If they'll have me. Somebody has to remember where the files are.","calm")],after='ask')
L('follow','thank',A,F,[("A year. I'm writing it down.","tender")],after='promise')
L('follow','press',A,F,[("That's what you always say.","glad")],after='deflect')
L('reply','tell',Y,F,[("The first budget. I said yes too fast, and I've been paying for it since.","tender")],after="Which one would you do over?")
L('reply','tell',Y,F,[("Then do me a favor. Tell them the truth about me, the good and the rest.","tender")],after='answer')
L('reply','promise',Y,F,[("Then I'll call you when I need to find a file. Which will be next week.","glad")],after='answer')
L('reply','tell',Y,F,[("It was. Most of it. Now grab the other end.","tender")],after='press')
L('reply','leave',Y,F,[("I'd better go before I get sentimental.","tender")])
L('close','accept',A,F,[("Too late for that. Go on.","tender")],after='leave',outcome='open')
L('close','accept',A,F,[("Go on. Don't look back at the building. Nobody ever does.","tender")],outcome='resolved')
F='poll-problem'
L(N,N,R,F,[("You give your name at the table in {place}. {name} runs a finger down the list twice.","braced")])
