L('follow','disagree',A,F,[("Defend it, then. Go ahead. I've got all afternoon.","braced")],after="I voted for it, and I'll own that. But I want to hear what it's doing to you before I defend it.")
L('follow','accept',A,F,[("Fine. I'll tell you. But you're going to hear the whole thing.","guarded")],after="I voted for it, and I'll own that. But I want to hear what it's doing to you before I defend it.")
L('follow','confront',A,F,[("Maybe not yours. It'll change mine, next time.","braced")],after="You're yelling at me in a parking lot. That's not going to change a vote.")
L('follow','accept',A,F,[("The floor. Fine. Don't act surprised when I show up.","guarded")],after="Come to the next council meeting. I'll make sure you get the floor before anyone else.")
L('follow','refuse',A,F,[("The floor. Where everybody nods and nobody changes a thing.","hurt")],after="Come to the next council meeting. I'll make sure you get the floor before anyone else.")
L('reply','tell',Y,F,[("That's fair. Nobody should find out what a law does to them from a stranger.","contrite")],after='answer')
L('reply','confront',Y,F,[("More people asked me for it than against it. That's the honest answer.","braced")],after='answer')
L('reply','leave',Y,F,[("I'm going to think about what you said. I mean that.","calm")],after='answer')
L('reply','confront',Y,F,[("Then vote me out. That's how this works.","braced")],after='confront')
L('reply','offer',Y,F,[("Or come say it where the rest of the council has to hear it too.","calm")],after='confront')
L('reply','promise',Y,F,[("Then I'll bring it up myself, and you can watch me do it.","calm")],after='refuse')
L('reply','tell',Y,F,[("I voted for it because the people who called me were for it. I didn't hear from you.","calm")],after='disagree')
L('reply','confront',Y,F,[("I don't owe you a debate next to a pickup truck.","braced")],after='disagree')
L('follow','accept',A,F,[("Well. At least you listened. That's more than I expected.","guarded")],after="That's fair. Nobody should find out what a law does to them from a stranger.")
L('follow','confront',A,F,[("Then they weren't living where I live.","hurt")],after="More people asked me for it than against it. That's the honest answer.")
L('follow','confront',A,F,[("Don't think I won't.","braced")],after="Then vote me out. That's how this works.")
L('follow','accept',A,F,[("Maybe I will. Save me a seat.","guarded")],after="Or come say it where the rest of the council has to hear it too.")
L('follow','thank',A,F,[("I'll be watching for it.","guarded")],after="Then I'll bring it up myself, and you can watch me do it.")
L('follow','confront',A,F,[("You didn't hear from me because nobody asked.","hurt")],after="I voted for it because the people who called me were for it. I didn't hear from you.")
L('follow','confront',A,F,[("No. You owe me a vote.","braced")],after="I don't owe you a debate next to a pickup truck.")
L('close','react',A,F,[("{name} gets in the truck without another word.","hurt")],after='leave',outcome='open')
L('close','warn',A,F,[("Remember this next time your name's on the ballot.","braced")],outcome='open')
L('close','thank',A,F,[("All right. I'll give you that one.","guarded")],outcome='resolved')
