F='mentor-advice'
L(N,N,R,F,[("{name} picked the diner, and the back booth, and already ordered for both of you. You came to ask about running for {office}.","calm")])
L('open','greet',A,F,[("Sit. The pie's the only thing worth eating here.","glad")])
L('state','tell',A,F,[("I'll say it before you ask: not this year. You're one good year away from being hard to beat.","calm")])
L('reply','ask',Y,F,[("What does one good year look like?","curious")])
L('reply','disagree',Y,F,[("Everybody says next year. Next year somebody else is already in the chair.","braced")])
L('reply','thank',Y,F,[("You might be the only person who'd tell me that to my face.","calm")])
L('reply','tell',Y,F,[("My family's already said yes. That was the hard part.","braced")])
L('reply','tell',Y,F,[("I can't afford to wait a year. I can barely afford this pie.","anxious",["asked_short_on_money"])])
