L('close','accept',A,F,[("Pie's on me. The advice was free.","glad")],after='leave',outcome='open')
L('close','thank',A,F,[("Call me before you tell anybody else.","calm")],outcome='resolved')
L('close','warn',A,F,[("Suit yourself. My number hasn't changed.","calm")],outcome='open')
