L('follow','offer',A,F,[("Here. The new location's on this sheet. It's ten minutes from here.","calm")],after="Then find out where they moved me.")
L('follow','apologize',A,F,[("You're not the first today. I'm writing every one of you down.","contrite")],after="Nobody sent me a single piece of mail about it.")
L('follow','offer',A,F,[("Two: the right place across town, or a provisional ballot here.","calm")],after="Okay. What are my options?")
L('reply','accept',Y,F,[("Provisional. Hand it over.","calm")],after='offer')
L('reply','request',Y,F,[("Write that down, too. I want a record I was here.","braced")],after='offer')
L('follow','offer',A,F,[("Already did. Sign here, and it's yours.","calm")],after="Write that down, too. I want a record I was here.")
L('reply','accept',Y,F,[("Fine. Give me the provisional.","calm")],after='apologize')
L('reply','request',Y,F,[("Then let's fix it. Who's in charge here?","calm")],after='apologize')
L('follow','offer',A,F,[("That's me today. Step over here and I'll walk you through it.","calm")],after="Then let's fix it. Who's in charge here?")
L('reply','confront',Y,F,[("Then make sure somebody actually counts this one.","braced")],after='deflect')
L('follow','apologize',A,F,[("I will. Personally.","contrite")],after="Then make sure somebody actually counts this one.")
L('close','accept',A,F,[("Good luck. Don't let the line over there scare you.","calm")],after='leave',outcome='open')
L('close','thank',A,F,[("Thanks for your patience. Next, please.","calm")],outcome='resolved')
F='victory-night'
L(N,N,R,F,[("Somebody's playing music too loud in the ballroom. {name}, who ran your campaign, steers you into the coat room and shuts the door.","glad")])
L('open','greet',A,F,[("You won. Say it out loud once before you go out there.","glad")])
L('state','ask',A,F,[("Then tell me what you're going to say about {opponent}. Ninety seconds, tops.","curious")])
L('reply','answer',Y,F,[("That they ran a clean race, and I'll need their people's help.","calm")])
L('reply','tell',Y,F,[("I'm not mentioning {opponent} at all. Tonight's about the volunteers.","glad")])
L('reply','ask',Y,F,[("Did {opponent} call yet?","curious")])
L('reply','boast',Y,F,[("That they'll be watching from home. Should be a short speech.","proud")])
L('reply','tell',Y,F,[("That six months ago I didn't have a job, and tonight I've got this one.","glad",["asked_out_of_work"])])
L('follow','accept',A,F,[("Say exactly that. Don't dress it up.","glad")],after="That six months ago I didn't have a job, and tonight I've got this one.")
L('follow','accept',A,F,[("Good. Grace plays better on the late news than a victory lap.","glad")],after="That they ran a clean race, and I'll need their people's help.")
L('follow','press',A,F,[("Clean race. Fine. But say their name, or it'll look like you're avoiding it.","guarded")],after="That they ran a clean race, and I'll need their people's help.")
L('follow','accept',A,F,[("The volunteers. They'll love that. Name the ones who did the phones.","glad")],after="I'm not mentioning {opponent} at all. Tonight's about the volunteers.")
L('follow','answer',A,F,[("Not yet. If {opponent} calls while you're on stage, I'll take a message.","guarded")],after="Did {opponent} call yet?")
L('follow','warn',A,F,[("Say that with a camera on you and it's the only clip they play.","braced")],after="That they'll be watching from home. Should be a short speech.")
L('reply','answer',Y,F,[("Then I'll say it once, kindly, and move on.","calm")],after='press')
L('reply','leave',Y,F,[("Okay. Open the door before I lose my nerve.","glad")],after='press')
L('follow','accept',A,F,[("Kindly. That's the speech.","glad")],after="Then I'll say it once, kindly, and move on.")
L('reply','tell',Y,F,[("Then I'll wait. I want to thank {opponent} before I thank anybody else.","calm")],after='answer')
L('reply','answer',Y,F,[("Take the message. I'm not holding the room.","calm")],after='answer')
L('follow','accept',A,F,[("That's the right call. Two more minutes, then.","glad")],after="Then I'll wait. I want to thank {opponent} before I thank anybody else.")
L('follow','accept',A,F,[("Taken. Go.","glad")],after="Take the message. I'm not holding the room.")
L('reply','apologize',Y,F,[("Fine. I'll keep it to myself until the after-party.","calm")],after='warn')
L('reply','boast',Y,F,[("We earned a little swagger tonight.","proud")],after='warn')
L('follow','accept',A,F,[("Good. The after-party's off the record. Mostly.","glad")],after="Fine. I'll keep it to myself until the after-party.")
L('close','warn',A,F,[("Your night. Your clip.","guarded")],outcome='open')
L('close','accept',A,F,[("Go. Smile at the cameras on the left.","glad")],after='leave',outcome='open')
L('close','thank',A,F,[("Go get 'em.","glad")],outcome='resolved')
F='concession-call'
L(N,N,R,F,[("The last precincts came in twenty minutes ago. {name}, your campaign manager, has the phone and hasn't dialed.","solemn")])
L('open','greet',A,F,[("I'm sorry. It's not going to turn around.","solemn")])
L('state','request',A,F,[("{opponent}'s team is waiting on the call. You should be the one to make it.","solemn")])
L('reply','agree',Y,F,[("Give me the phone.","solemn")])
L('reply','ask',Y,F,[("How close was it?","braced")])
L('reply','refuse',Y,F,[("I'm not calling anybody until the county certifies it.","braced")])
L('reply','stall',Y,F,[("Let me talk to the volunteers first.","hurt")])
L('reply','tell',Y,F,[("I quit a paying job for this. I need a minute before I say it out loud.","hurt",["asked_out_of_work"])])
L('follow','press',A,F,[("Take the minute. Then make the call. Your name's still worth something tomorrow.","tender")],after="I quit a paying job for this. I need a minute before I say it out loud.")
L('follow','thank',A,F,[("Here. Keep it short. Say you'll help.","solemn")],after="Give me the phone.")
L('follow','answer',A,F,[("Closer than anybody expected. Not close enough to count again.","solemn")],after="How close was it?")
L('follow','press',A,F,[("Certification takes a week. Every hour you wait, it looks worse.","braced")],after="I'm not calling anybody until the county certifies it.")
L('follow','plea',A,F,[("They'll understand if you call first. They're going to cry either way.","tender")],after="Let me talk to the volunteers first.")
L('follow','press',A,F,[("The volunteers already know. They're waiting on you to say it.","tender")],after="Let me talk to the volunteers first.")
L('reply','agree',Y,F,[("Closer than anybody expected. I can live on that. Dial it.","solemn")],after='answer')
L('reply','refuse',Y,F,[("Then it's close enough to wait for the last count.","braced")],after='answer')
L('reply','agree',Y,F,[("All right. I'll make the call.","solemn")],after='press')
L('reply','refuse',Y,F,[("Let it look worse. I'm not conceding a race I might have won.","braced")],after='press')
L('reply','agree',Y,F,[("Okay. The call first. Then them.","solemn")],after='plea')
L('reply','leave',Y,F,[("I need some air before I do either.","hurt")])
L('follow','thank',A,F,[("Thank you. I'll get them on the line.","solemn")],after='agree')
L('follow','press',A,F,[("You didn't win it. I'm sorry. I counted twice.","tender")],after="Let it look worse. I'm not conceding a race I might have won.")
L('close','accept',A,F,[("I'll be right here when you come back in.","tender")],after='leave',outcome='open')
L('close','thank',A,F,[("You did good. It just wasn't enough.","tender")],outcome='resolved')
L('close','warn',A,F,[("Okay. But the morning papers won't wait.","solemn")],outcome='open')
F='floor-switch'
L(N,N,R,F,[("The clerk is calling names on {bill}. {name} slides into the empty chair next to you and leans close.","braced")])
L('open','greet',A,F,[("Don't look at me. Look at the board.","braced")])
L('state','request',A,F,[("We're one vote down. When they get to you, I need a yes.","braced")])
L('reply','ask',Y,F,[("Why are you asking me and not the three people behind me?","guarded")])
L('reply','agree',Y,F,[("If it's that close, you've got it.","guarded")])
L('reply','refuse',Y,F,[("You knew my answer last week. It hasn't changed.","braced")])
L('reply','bargain',Y,F,[("My road money's still sitting in committee. Get it out, and I'm yes.","calm")])
L('reply','stall',Y,F,[("I'll decide when I hear my name.","guarded")])
L('follow','answer',A,F,[("Because those three can't afford a yes, and you can.","braced")],after="Why are you asking me and not the three people behind me?")
L('follow','thank',A,F,[("I won't forget it. Neither will the leadership.","glad")],after="If it's that close, you've got it.")
L('follow','plea',A,F,[("It's changed for me. I'm asking as a friend this time.","tender")],after="You knew my answer last week. It hasn't changed.")
L('follow','threaten',A,F,[("Then don't expect the leadership to remember your name in the spring.","braced")],after="You knew my answer last week. It hasn't changed.")
L('follow','accept',A,F,[("Done. I'll walk it over to the chair myself tonight.","calm")],after="My road money's still sitting in committee. Get it out, and I'm yes.")
L('follow','refuse',A,F,[("I can't move committee money in ten minutes. Nobody can.","guarded")],after="My road money's still sitting in committee. Get it out, and I'm yes.")
L('follow','press',A,F,[("They're at the G's. You're going to hear it in about a minute.","braced")],after="I'll decide when I hear my name.")
L('reply','agree',Y,F,[("Fine. Yes. Don't make me regret it.","guarded")],after='answer')
L('reply','refuse',Y,F,[("Afford is a funny word for it. No.","braced")],after='answer')
L('reply','bargain',Y,F,[("Then it costs you something. What've you got?","calm")],after='answer')
L('follow','bargain',A,F,[("My name on your next bill, as a co-sponsor. That's real.","calm")],after="Then it costs you something. What've you got?")
L('reply','agree',Y,F,[("That's real. Yes.","calm")],after="My name on your next bill, as a co-sponsor. That's real.")
L('reply','refuse',Y,F,[("That's a line on paper. No.","braced")],after="My name on your next bill, as a co-sponsor. That's real.")
L('reply','agree',Y,F,[("As a friend. Fine. Just this once.","guarded")],after='plea')
L('reply','refuse',Y,F,[("As a friend, I'm telling you no.","braced")],after='plea')
L('reply','refuse',Y,F,[("They'll remember me fine. I'll remind them.","braced")],after='threaten')
L('reply','threaten',Y,F,[("And I'll remember who threatened me on the floor.","braced")],after='threaten')
L('follow','accept',A,F,[("Fair. Forget I said it.","guarded")],after="And I'll remember who threatened me on the floor.")
L('reply','agree',Y,F,[("All right. Yes. Go sit down.","guarded")],after='press')
L('reply','refuse',Y,F,[("Then you'll hear a no in about a minute.","braced")],after='press')
L('reply','agree',Y,F,[("Then get it out next session, and I'll still vote yes tonight.","calm")],after='refuse')
L('reply','refuse',Y,F,[("Then I can't move my vote in ten minutes either.","braced")],after='refuse')
L('follow','thank',A,F,[("Thank you. Really.","glad")],after='agree')
L('close','warn',A,F,[("Hope your district thanks you for it.","braced")],outcome='refused')
L('close','accept',A,F,[("Clerk's on you. Make it count.","braced")],after='leave',outcome='open')
L('close','thank',A,F,[("I owe you one. A real one.","glad")],outcome='resolved')
L('reply','leave',Y,F,[("Go work the back row. I'm not your vote tonight.","braced")])
F='signing-ask'
L(N,N,R,F,[("The signing's over, and staff are stacking the chairs. {name}, the {executive}, hands you one of the pens.","glad")])
L('open','greet',A,F,[("Keep it. You earned it.","glad")])
L('state','request',A,F,[("I've got a bill of my own coming. I'd like your name on it before anybody else's.","calm")])
L('reply','agree',Y,F,[("You've got it. Send it over tonight.","calm")])
L('reply','ask',Y,F,[("Which bill? You've got four.","guarded")])
L('reply','refuse',Y,F,[("I sign onto bills I've read. I'll read yours.","braced")])
L('reply','bargain',Y,F,[("I'll go first if you go easy on my district's line in the budget.","calm")])
L('follow','thank',A,F,[("Tonight. You're a good partner.","glad")],after="You've got it. Send it over tonight.")
L('follow','answer',A,F,[("My budget. It comes to the floor next month, and your district's in it.","calm")],after="Which bill? You've got four.")
L('follow','warn',A,F,[("Read it fast. Everyone else is going to want to be second.","guarded")],after="I sign onto bills I've read. I'll read yours.")
L('follow','accept',A,F,[("Fair enough. Reading's a lost art.","calm")],after="I sign onto bills I've read. I'll read yours.")
L('follow','accept',A,F,[("Easy is a big word. Lighter, I can do.","calm")],after="I'll go first if you go easy on my district's line in the budget.")
L('follow','refuse',A,F,[("The budget's the budget. I can't trade a line for a name.","guarded")],after="I'll go first if you go easy on my district's line in the budget.")
L('reply','agree',Y,F,[("The budget. Send it. I'll go first.","calm")],after='answer')
L('reply','refuse',Y,F,[("Send it. I'll tell you after I've read it.","braced")],after='answer')
L('reply','bargain',Y,F,[("Then let my office write the part about my district.","calm")],after='answer')
L('follow','accept',A,F,[("Done. Your office writes your district's part.","glad")],after="Then let my office write the part about my district.")
L('reply','agree',Y,F,[("Then I'll read fast.","calm")],after='warn')
L('reply','confront',Y,F,[("Then let them be first.","braced")],after='warn')
L('follow','warn',A,F,[("Maybe I will.","guarded")],after="Then let them be first.")
L('reply','agree',Y,F,[("Lighter works. You'll have my name.","calm")],after='accept')
L('close','thank',A,F,[("Pleasure doing business.","glad")],outcome='resolved')
L('close','warn',A,F,[("We'll see who's first, then.","guarded")],outcome='open')
L('close','accept',A,F,[("Go. Enjoy the pen.","glad")],after='leave',outcome='open')
L('reply','leave',Y,F,[("Let me get through tonight first.","calm")])
F='veto-call'
L(N,N,R,F,[("You're halfway through dinner when the phone buzzes: the {executive}'s office. It's {name} on the line.","braced")])
L('open','greet',A,F,[("Sorry to interrupt your evening.","calm")])
L('state','tell',A,F,[("I'm going to veto {bill} tomorrow morning. I wanted you to hear it from me.","calm")])
L('reply','ask',Y,F,[("What changed? Two weeks ago you were for it.","braced")])
L('reply','confront',Y,F,[("Then we'll override it. I've got the votes.","braced")])
L('reply','bargain',Y,F,[("Tell me what you'd sign, and I'll get you a new draft.","calm")])
L('reply','accept',Y,F,[("Thanks for the warning. I'll tell my people.","guarded")])
L('follow','answer',A,F,[("The cost estimate came in. It's nearly double what we were told.","calm")],after="What changed? Two weeks ago you were for it.")
L('follow','confront',A,F,[("Maybe. Count them again before you say it to a reporter.","braced")],after="Then we'll override it. I've got the votes.")
L('follow','accept',A,F,[("Phase it in over three years, and I'll sign it the day it lands.","calm")],after="Tell me what you'd sign, and I'll get you a new draft.")
L('follow','thank',A,F,[("I appreciate that. I know this one stings.","calm")],after="Thanks for the warning. I'll tell my people.")
L('reply','confront',Y,F,[("Double because your budget office padded it.","braced")],after='answer')
L('reply','bargain',Y,F,[("Then let's cut it in half. Would you sign half?","calm")],after='answer')
L('reply','accept',Y,F,[("If that's the number, I understand. I don't like it.","guarded")],after='answer')
L('follow','confront',A,F,[("Then prove it on the floor. That's what it's for.","braced")],after="Double because your budget office padded it.")
L('follow','accept',A,F,[("Half, phased in. Yes, I'd sign that.","calm")],after="Then let's cut it in half. Would you sign half?")
L('follow','thank',A,F,[("Neither do I. Thank you for understanding.","calm")],after="If that's the number, I understand. I don't like it.")
L('reply','confront',Y,F,[("I counted twice before I picked up the phone.","braced")],after='confront')
L('reply','bargain',Y,F,[("Or we skip the fight and you tell me what you'd sign.","calm")],after='confront')
L('follow','confront',A,F,[("Then I'll see the tally like everybody else.","braced")],after="I counted twice before I picked up the phone.")
L('follow','accept',A,F,[("That's the smarter call. Send me a draft.","calm")],after="Or we skip the fight and you tell me what you'd sign.")
L('reply','leave',Y,F,[("I need to call the sponsors before this gets out.","braced")])
L('close','warn',A,F,[("Then we'll see what the floor decides.","braced")],outcome='open')
L('close','accept',A,F,[("Go. Call them before the paper does.","calm")],after='leave',outcome='open')
L('close','thank',A,F,[("Send it when it's ready. My door's open.","calm")],outcome='resolved')
F='appointment-offer'
L(N,N,R,F,[("You're at your desk when {name} calls from the {executive}'s office. The voice is friendly and very careful.","curious")])
L('open','greet',A,F,[("Do you have ten minutes? This isn't a call to make in a hallway.","calm")])
L('state','offer',A,F,[("The {executive} wants to name you {office}. You'd have to step down from your seat to take it.","calm")])
L('reply','agree',Y,F,[("Yes. Tell the {executive} yes.","glad")])
L('reply','ask',Y,F,[("Why would the {executive} want me? I've voted against half that agenda.","guarded")])
L('reply','decline',Y,F,[("I'm flattered. I'm also not leaving my seat.","braced")])
L('reply','ask',Y,F,[("What would the job actually be, day to day?","curious")])
L('reply','stall',Y,F,[("I'll need to talk it over at home. I'm not deciding this alone.","calm",["asked_partner"])])
L('follow','accept',A,F,[("Of course. Take the weekend. The offer will keep that long.","calm")],after="I'll need to talk it over at home. I'm not deciding this alone.")
L('follow','thank',A,F,[("Wonderful. Someone will call tomorrow with the paperwork.","glad")],after="Yes. Tell the {executive} yes.")
L('follow','answer',A,F,[("That's exactly why. You'd say no to the right people.","calm")],after="Why would the {executive} want me? I've voted against half that agenda.")
L('follow','press',A,F,[("Think about how much more you could do from this chair than that one.","calm")],after="I'm flattered. I'm also not leaving my seat.")
L('follow','answer',A,F,[("Long days, a staff of forty, and every hard call on your desk first.","calm")],after="What would the job actually be, day to day?")
L('reply','agree',Y,F,[("When you put it like that, yes.","glad")],after='answer')
L('reply','stall',Y,F,[("Tell the {executive} I'll talk. That's all I'm saying today.","guarded")],after='answer')
L('reply','decline',Y,F,[("That's a job for someone who wants it more than I do.","calm")],after='answer')
L('reply','ask',Y,F,[("And who fills my seat if I go?","curious")],after='answer')
L('follow','answer',A,F,[("The {executive} would appoint someone until the next election. That's how it works.","calm")],after="And who fills my seat if I go?")
L('follow','accept',A,F,[("Talking's a start. I'll set up the meeting.","calm")],after="Tell the {executive} I'll talk. That's all I'm saying today.")
L('follow','accept',A,F,[("Understood. I'll pass that along.","calm")],after="That's a job for someone who wants it more than I do.")
L('reply','agree',Y,F,[("More than I'd like to admit. Okay. Yes.","glad")],after='press')
L('reply','decline',Y,F,[("From this chair I answer to my neighbors. That's what I want.","braced")],after='press')
L('follow','accept',A,F,[("Then I'll tell the {executive} you said no, and why. It'll land well.","calm")],after="From this chair I answer to my neighbors. That's what I want.")
L('reply','leave',Y,F,[("Let me call you back tomorrow.","calm")])
L('close','accept',A,F,[("Tomorrow, then. Don't make me chase you.","calm")],after='leave',outcome='open')
L('close','thank',A,F,[("Congratulations. Really.","glad")],outcome='resolved')
L('close','warn',A,F,[("The offer won't sit on the desk long.","calm")],outcome='open')
F='recall-confront'
L(N,N,R,F,[("A card table has gone up by the post office doors. {name} is behind it with petitions and a jar of pens.","braced")])
L('open','greet',A,F,[("I figured you'd come by eventually.","braced")])
L('state','confront',A,F,[("This is a recall petition with your name on it. It's about {bill}.","braced")])
L('reply','ask',Y,F,[("What does it say I did?","calm")])
L('reply','confront',Y,F,[("A recall over one vote? That's not how this is supposed to work.","braced")])
L('reply','boast',Y,F,[("Get your signatures. I'll take my chances on a ballot.","proud")])
L('reply','deflect',Y,F,[("I'm just here for stamps.","guarded")])
L('reply','leave',Y,F,[("I'm not going to argue with you in front of the post office.","guarded")])
L('follow','answer',A,F,[("That you voted for {bill} after telling us you wouldn't.","braced")],after="What does it say I did?")
L('follow','confront',A,F,[("It's exactly how it's supposed to work. You answer to us.","braced")],after="A recall over one vote? That's not how this is supposed to work.")
L('follow','confront',A,F,[("You might. You'd have to explain yourself on that ballot, though.","braced")],after="Get your signatures. I'll take my chances on a ballot.")
L('follow','press',A,F,[("The stamp line can wait two minutes. Can you?","braced")],after="I'm just here for stamps.")
L('reply','tell',Y,F,[("I said I'd look hard at it. I looked, and I changed my mind. That's the truth.","calm")],after='answer')
L('reply','confront',Y,F,[("I never said that. Show me where I said that.","braced")],after='answer')
L('follow','accept',A,F,[("Then say that to the people signing. Some of them might listen.","guarded")],after="I said I'd look hard at it. I looked, and I changed my mind. That's the truth.")
L('follow','confront',A,F,[("Page two of your mailer. I've got a copy right here.","braced")],after="I never said that. Show me where I said that.")
L('reply','confront',Y,F,[("Then show me the copy.","braced")],after='confront')
L('reply','tell',Y,F,[("Then let me explain the vote to anyone who stops. I'll stand right here.","calm")],after='confront')
L('reply','boast',Y,F,[("I've won worse races than a recall.","proud")],after='confront')
L('follow','confront',A,F,[("Here. Read it out loud.","braced")],after="Then show me the copy.")
L('follow','accept',A,F,[("Fine by me. It's a public sidewalk.","guarded")],after="Then let me explain the vote to anyone who stops. I'll stand right here.")
L('follow','confront',A,F,[("Not against your own neighbors.","braced")],after="I've won worse races than a recall.")
L('reply','offer',Y,F,[("Two minutes, then. Ask me anything about the vote.","calm")],after='press')
L('reply','confront',Y,F,[("I don't owe you two minutes at a card table.","braced")],after='press')
L('follow','thank',A,F,[("Okay. I'm listening. Start with why you changed your mind.","curious")],after="Two minutes, then. Ask me anything about the vote.")
L('follow','confront',A,F,[("No. You owe it to the people signing.","braced")],after="I don't owe you two minutes at a card table.")
L('close','warn',A,F,[("We'll be out here every Saturday until it's done.","braced")],after='leave',outcome='open')
L('close','warn',A,F,[("Your name's on the clipboard either way.","braced")],outcome='open')
L('close','thank',A,F,[("Fair enough. That's more than most give us.","guarded")],outcome='resolved')
F='hearing-testify'
L(N,N,R,F,[("The meeting runs late, and public comment on {bill} starts after nine. {name} reads your name off the sign-up sheet.","braced")])
L('open','greet',A,F,[("Three minutes, please. The light turns yellow at thirty seconds.","calm")])
L('state','ask',A,F,[("Name and address for the record, then go ahead.","calm")])
L('reply','tell',Y,F,[("{self}, {place}. I'm here because this bill changes my street, and nobody asked my street.","braced")])
L('reply','request',Y,F,[("{self}, {place}. I'm asking you to delay the vote until you hold one meeting in the neighborhood.","calm")])
L('reply','confront',Y,F,[("{self}, {place}. Every one of you has already decided, and I'd like that on the record.","braced")])
L('reply','ask',Y,F,[("{self}, {place}. Can someone tell me who asked for this bill?","curious")])
